const alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'},uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'},hash={type:'string',pattern:'^[a-f0-9]{64}$'};
const text={type:'string'},label={type:'string',minLength:1,maxLength:160};
const scope={workspace:alias,workspaceId:uuid},request={requestId:uuid,expectedVersion:{type:'integer',minimum:0}};
const page={offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:100}};
const chunk={expectedSha256:hash,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES},readId:uuid};
const read={readOnly:true,idempotent:true},write={idempotent:true,openWorld:true};
export function frictionlessWorkspaceTools(tool){
 const scoped=(name,description,properties={},required=[],annotations=read)=>tool('merchant_frictionless_'+name,description,{...scope,...properties},['workspace','workspaceId',...required],annotations);
 return[
  tool('merchant_frictionless_status','List host-declared Frictionless source workspaces without opening them, or page the original retained captures, editions and request history.',{...scope,limit:page.limit,capturesOffset:page.offset,editionsOffset:page.offset,operationsOffset:page.offset},[],read),
  tool('merchant_frictionless_open','Borrow the configured original Frictionless publisher and its existing scheduler. Returns the persistent source-workbench UUID and distinct owner instance IDs.',{workspace:alias},['workspace'],write),
  scoped('close','Drain this exact borrowed source browser, immutable file reads and model. The existing merchant publisher remains with its original owner.',{instanceId:uuid,publisherInstanceId:uuid},['instanceId','publisherInstanceId'],{destructive:true}),
  scoped('current','Inspect the currently selected ORIGINAL publisher source, source/capture hashes and original query declarations. Opens no new capture.'),
  scoped('input','Inspect one host-declared descriptor/source archive or builtin current input before an explicit new intake; local inputs return their exact SHA-256.',{input:alias},['input']),
  scoped('intake','Retain an explicit new immutable capture from a host input. This calls the original capture/source-receive path and records a stable request before work. Local/current inputs require the inspected original SHA.',{...request,input:alias,expectedSha256:hash,label},['requestId','expectedVersion','input','label'],write),
  scoped('capture','Read the original package metadata, full resource/schema/physical inspection, suggested queries or paginated declared files. Field values are never reconstructed by this workbench.',{captureId:uuid,section:{enum:['overview','resource','queries','files']},resource:text,...page},['captureId']),
  scoped('edition','Inspect an immutable source edition, or create one from explicit ordered original query projections. Schema overrides require original captured reference evidence.',{action:{enum:['inspect','create']},editionId:uuid,captureId:uuid,...request,label,queries:{type:'object',minProperties:1,maxProperties:64},queriesText:{type:'string',maxLength:8388608,description:'Exact original query JSON text; choose this instead of queries for imported constraints or integers outside the browser exact range.'}},['action'],write),
  scoped('review','Run every original selected row through the existing native source review and retain reviewer/note, or inspect an exact completed review. Validation findings remain visible and do not become approval.',{action:{enum:['inspect','run']},reviewId:uuid,editionId:uuid,...request,reviewer:{type:'string',minLength:1,maxLength:80},note:{type:'string',minLength:1,maxLength:2000}},['action'],write),
  scoped('plan_input','Get the original Frictionless publication plan template for one exact immutable edition/query. Review this complete template before saving.',{editionId:uuid,query:text},['editionId','query']),
  scoped('select','Select a fully reviewed immutable source under the SAME original publisher writer, with compare-and-swap of the current source hash. Earlier plans and source bytes stay retained.',{...request,editionId:uuid,reviewId:uuid,expectedSourceHash:hash},['requestId','expectedVersion','editionId','reviewId','expectedSourceHash'],write),
  scoped('plan','Save the exact reviewed publication plan through the original publisher using this same stable request UUID. It preserves projection order and recovers the original plan after response loss.',{...request,editionId:uuid,reviewId:uuid,plan:{type:'object'}},['requestId','expectedVersion','editionId','reviewId','plan'],write),
  scoped('compare','Create a retained comparison of original data-file hashes, schemas, dialects and descriptors, or inspect it. This is not a row-level diff or a measured scientific outcome.',{action:{enum:['create','inspect']},comparisonId:uuid,...request,before:uuid,after:uuid,label},['action'],write),
  scoped('export','Export a complete original source archive plus frozen source-edition/review/selection history and receiving guide, or inspect its original request. This source export does not include the publisher dataset or a customer warehouse.',{action:{enum:['create','inspect']},...request,editionId:uuid,reviewId:uuid,label},['action','requestId'],write),
  scoped('request','Inspect a retained source request or explicitly resume its exact saved input. Reading never replays a mutation; new UUIDs represent new actions.',{action:{enum:['inspect','resume']},requestId:uuid},['action','requestId'],write),
  scoped('cancel','Request cancellation of only the original active source job; retained native output and request history survive for explicit same-request continuation.',{requestId:uuid,operationId:uuid},['requestId','operationId'],write),
  scoped('file','Read exact declared capture, source-edition, review, comparison or completed export bytes using the original immutable descriptor reader and digest/offset binding.',{kind:{enum:['capture','edition','review','comparison','export']},id:uuid,file:text,...chunk},['kind','id','file','expectedSha256']),
  scoped('file_release','Release the exact source file read without closing the source workspace.',{readId:uuid},['readId'],write),
  scoped('export_manifest','Inspect the complete original source-export download manifest, including all declared native source and review files.',{exportId:uuid},['exportId']),
  scoped('export_file','Read a full declared source-export file, bound to original manifest and file hashes. The maintained client supports interruption and owner reopen without replacing earlier bytes.',{exportId:uuid,file:text,expectedManifestSha256:hash,...chunk},['exportId','file','expectedManifestSha256','expectedSha256']),
  scoped('export_file_release','Release an exact source-export read; the retained source and download checkpoint remain unchanged.',{exportId:uuid,readId:uuid},['exportId','readId'],write),
  scoped('browser','Open/reuse or close the source workbench on the SAME publisher, scheduler and model. Returns its trusted local browser URL without starting another publisher.',{action:{enum:['open','close']},port:{type:'integer',minimum:0,maximum:65535}},['action'],write),
 ];
