      (stat.mode & 0o077) || (typeof process.getuid === 'function' && stat.uid !== process.getuid()))
    throw error('QUOTE_STORAGE_PERMISSIONS', 'Quote storage must be owned by this user and private (0700 directory, 0600 files).');
