    let directory;
    try { directory = dirname(fileURLToPath(import.meta.resolve('@modelcontextprotocol/sdk/client/index.js'))); }
    catch { fail('MCP_SDK_NOT_INSTALLED', `Install @modelcontextprotocol/sdk@${MCP_SDK_VERSION}.`); }
