const ROOT = fileURLToPath(new URL(".", import.meta.url));
const ORIGINALS = [
  { path: "fixture-event-simple.json", git: "3b6936894172b4fc78f9b385771695fb6e2a8720" },
  { path: "fixture-event-full.json", git: "d0f19663859955c95afde83bd7bd3fcdffc641e8" }
