      definition.configurationSha256 === binding.configurationSha256 &&
      definition.expectedSnapshot === binding.expectedSnapshot &&
      canonical(definition.limits) === canonical(binding.limits) &&
      (definition.workspaceDirectory ?? null) === binding.workspaceDirectory,
    'DATASET_APPLICATION_BINDING_CHANGED');
    return {kind:'dataset', id:this.id, entryDirectory:this.directory,
      sessionDirectory:metadata.sessionDirectory, sessionId:binding.sessionId,
      configurationSha256:binding.configurationSha256, workspace:binding.workspaceDirectory};
  }
  async _accounting(action, input, {initialize = false} = {}) {
    const options = accountingOptions(input, action === 'finalize');
    const identity = await this._accountingIdentity({allowUnbound:initialize});
    return runAccounting(this, identity, action, options, {outputFile:'native.json',
      invoke:async ({directory, signal, resultFile}) => {
        const {signal:unused, ...request} = options;
        const requestPath = join(directory, 'request.json');
        await writeJson(requestPath, {...request, reportLimit:this.buyer.datasetReportLimit,
          initializeAccounting:initialize}, {exclusive:true});
        return this.buyer.runtime.run([this.buyer.runtime.directory, this.directory, action, requestPath, resultFile],
          {directory, signal, entryFile:WORKER, resultFile, resultLimit:this.buyer.datasetReportLimit});
      }});
  }
  /** Original page views, available independently of delivered dataset bytes. */
  accounting(options) { return this._accounting('accounting', options); }
  /** Attach an original financial account even after delivered pages were removed. */
  async initializeAccounting(options) {
    need((await this._metadata()).source.kind === 'attached', 'DATASET_ACCOUNTING_ATTACHMENT_REQUIRED');
    return this._accounting('accounting', options, {initialize:true});
  }
  /** Continue existing reservations through the original SF36/SF86 finalizer. */
  finalize(options) { return this._accounting('finalize', options); }
  accountingPages(options) { return accountingPages(this, options); }
  finalizeAll(options) { return accountingPages(this, options, true); }
  async recoverAccounting(options) {
    return recoverAccounting(this, await this._accountingIdentity(), options);
  }
  exportAccounting(destination, options) { return exportAccounting(this, destination, options); }
  async exportManifest(destination, options) {
    return this._command('manifest', {destination:absolute(destination)}, options);
  }
  /** Builds or reopens the original SF100 data room, entirely offline. */
  async deliver(destination = join(this.directory, 'delivery'), options) {
    const result = await this._command('deliver', {destination:absolute(destination)}, options);
    need(result.process.exitCode === 0 && !result.process.errorCode,
      result.process.errorCode ?? 'DATASET_DELIVERY_NOT_COMPLETE');
    return DatasetDelivery.open(result.native);
  }
}

export async function createDataset(buyer, options, attached = false) {
  need(object(options), 'DATASET_OPTIONS_REQUIRED');
  const {id, config, workspaceDirectory, directory, operatorProfile,
    maxPages, maxTotalAtomic, maxRows = 1000000, maxPageBytes = 1048576, expectedSnapshot = null,
    accountingOnly = false, recoveryOnly = false} = options;
  need(typeof accountingOnly === 'boolean' && (attached || !accountingOnly), 'DATASET_ACCOUNTING_ATTACHMENT_REQUIRED');
  need(typeof recoveryOnly==='boolean'&&(attached||!recoveryOnly)&&!(recoveryOnly&&accountingOnly),
    'DATASET_RECOVERY_ATTACHMENT_REQUIRED');
  const dataset = new Dataset(buyer, id);
  await buyer.ready();
  await privateDirectory(join(buyer.stateDirectory, 'datasets'));
  const metadata = {schema:SCHEMA, id:dataset.id, entryDirectory:dataset.directory,
    sessionDirectory:attached ? absolute(directory) : join(dataset.directory, 'session'),
    createdAt:now(), source:attached ? {kind:'attached'} : workspaceDirectory !== undefined
      ? {kind:'workspace', directory:absolute(workspaceDirectory)} : {kind:'config'}};
  let input;
  if (!attached) {
    need((config !== undefined) !== (workspaceDirectory !== undefined), 'DATASET_ONE_CONFIG_SOURCE_REQUIRED');
    if (workspaceDirectory !== undefined) need(operatorProfile === undefined, 'DATASET_WORKSPACE_PROFILE_UNSUPPORTED');
    metadata.limits = {maxPages,maxTotalAtomic,maxRows,maxPageBytes};
    metadata.expectedSnapshot = expectedSnapshot;
    // Reject non-JSON values before allocating a named application entry.
    jsonBytes(metadata);
    if (config !== undefined) input = await buyer._profile(typeof config === 'string'
      ? await readJson(absolute(config)) : clone(config), operatorProfile);
  }
  if (await exists(dataset.directory)) throw new BuyerError('DATASET_ALREADY_EXISTS_USE_OPEN', {dataset});
  const parent = join(buyer.stateDirectory, 'datasets');
  // Publish a complete entry once. A crash while writing the private stage cannot
  // reserve the stable name or make listDatasets encounter half-written metadata.
  const stage = await mkdtemp(join(parent, '.dataset-stage-'));
  if (input) await writeJson(join(stage, 'config.json'), input, {exclusive:true});
  await writeJson(join(stage, 'dataset.json'), metadata, {exclusive:true});
  await syncDirectory(stage);
  try { await rename(stage, dataset.directory); }
  catch (error) {
    // A concurrently published entry is nonempty and cannot be replaced by rename.
    if (['EEXIST','ENOTEMPTY'].includes(error.code))
      throw new BuyerError('DATASET_ALREADY_EXISTS_USE_OPEN', {dataset, stagingDirectory:stage});
    throw error;
  }
  await syncDirectory(parent);
  if (recoveryOnly) await dataset.initializeRecovery();
  else if (accountingOnly) await dataset.initializeAccounting();
  else await dataset.initialize();
  return dataset;
}

export async function* listDatasets(buyer) {
  await buyer.ready();
  const directory = join(buyer.stateDirectory, 'datasets');
  if (!await exists(directory)) return;
  await privateDirectory(directory, {create:false});
  for (const entry of await readdir(directory, {withFileTypes:true})) {
    if (!entry.isDirectory() || !/^[a-f0-9]{64}$/.test(entry.name)) continue;
    const metadata = await readJson(join(directory, entry.name, 'dataset.json'));
    need(metadata.schema === SCHEMA && digest(intent(metadata.id)) === entry.name,
      'DATASET_APPLICATION_STATE_INVALID');
    yield new Dataset(buyer, metadata.id);
  }
}

/** A file from an original, verified SF100 export. No native purchase summary is fabricated. */
export class DatasetFile extends VerifiedFile {
  constructor(metadata, directory) {
    super();
    this.metadata = freeze(clone(metadata));
    this.directory = absolute(directory);
  }
  _metadata() {
    const saved = this.metadata;
    need(object(saved) && OUTPUTS.has(saved.name) && saved.path === join(this.directory, saved.name) &&
      Number.isSafeInteger(saved.bytes) && saved.bytes >= 0 && saved.bytes <= MAX_OUTPUT &&
      typeof saved.sha256 === 'string' && /^[a-f0-9]{64}$/.test(saved.sha256),
    'DATASET_OUTPUT_METADATA_INVALID');
    return saved;
  }
}

export class DatasetDelivery {
  constructor(report, manifest) {
    this.report = freeze(clone(report));
    this.manifest = freeze(clone(manifest));
  }
  static async open(report) {
    need(report?.schema === 'stellar-forge.sf88.dataset-delivery.v1' &&
      report.nativeStatus?.finalized === true && object(report.outputs), 'DATASET_NATIVE_DELIVERY_INVALID');
    const file = new DatasetFile({name:'manifest.json', ...report.outputs['manifest.json']}, report.directory);
    const manifest = await file.json({limit:4 * 1024 * 1024});
    need(manifest?.schema === 'stellar-forge.buyer-delivery-manifest.v1' &&
      manifest.dataset?.snapshot === report.nativeStatus.snapshot &&
      manifest.dataset.rows === report.nativeStatus.rows && Array.isArray(manifest.dataset.projectedFields) &&
      object(manifest.outputs), 'DATASET_NATIVE_MANIFEST_INVALID');
    const semantics = manifest.semantics;
    need((semantics !== undefined) === (report.semantics !== undefined),
      'DATASET_SEMANTIC_OUTPUT_METADATA_INVALID');
    if (semantics !== undefined) need(object(semantics) && semantics.file === 'semantics.json' &&
      semantics.scope === 'PUBLISHED_DATASET' && semantics.typedRowsFile === 'dataset.jsonl' &&
      ['schema','sha256','definitionSha256','captureManifestSha256'].every(key =>
        semantics[key] === report.semantics[key] && semantics[key] === report.nativeStatus.semantics?.[key]) &&
      JSON.stringify(semantics.selectedFields) === JSON.stringify(manifest.dataset.projectedFields),
      'DATASET_SEMANTIC_OUTPUT_METADATA_INVALID');
    for (const name of ['dataset.jsonl','dataset.csv','review.html',
      ...(semantics !== undefined ? ['semantics.json'] : [])])
      need(manifest.outputs[name]?.sha256 === report.outputs[name]?.sha256 &&
        manifest.outputs[name]?.bytes === report.outputs[name]?.bytes, 'DATASET_OUTPUT_METADATA_INVALID');
    return new DatasetDelivery(report, manifest);
  }
  file(name) {
    need(OUTPUTS.has(name), 'DATASET_OUTPUT_NAME_INVALID');
    return new DatasetFile({name, ...this.report.outputs[name]}, this.report.directory);
  }
  /** The retained published dictionary; selectedFields remain in the delivery manifest. */
  async readSemantics({limit = 2097152, signal} = {}) {
    if (this.manifest.semantics === undefined) return null;
    const value = await this.file('semantics.json').json({limit, signal});
    const binding = this.manifest.semantics;
    need(value?.schema === binding.schema && value.sha256 === binding.sha256 &&
      value.definitionSha256 === binding.definitionSha256 &&
      value.source?.captureManifestSha256 === binding.captureManifestSha256,
      'DATASET_SEMANTIC_DICTIONARY_CHANGED');
    return value;
  }
  _row(text) {
    let value;
    try { value = JSON.parse(text); } catch { throw new BuyerError('DATASET_ROW_JSON_INVALID'); }
    const fields = this.manifest.dataset.projectedFields;
    need(object(value) && Object.keys(value).length === fields.length && fields.every(field =>
      Object.hasOwn(value, field) && (value[field] === null || ['string','number','boolean'].includes(typeof value[field]))),
    'DATASET_ROW_SHAPE_INVALID');
    return value;
  }
  /** Values retain the original SF100 JSON scalar types; no numeric/date coercion. */
  async *rows({signal, maxRowCharacters = 16777216} = {}) {
    need(Number.isSafeInteger(maxRowCharacters) && maxRowCharacters > 0 && maxRowCharacters <= MAX_OUTPUT,
      'DATASET_ROW_LIMIT_INVALID');
    const decoder = new TextDecoder('utf-8', {fatal:true});
    let pending = '', count = 0;
    for await (const chunk of this.file('dataset.jsonl').chunks({signal})) {
      pending += decoder.decode(chunk, {stream:true});
      let newline;
      while ((newline = pending.indexOf('\n')) >= 0) {
        need(newline <= maxRowCharacters, 'DATASET_ROW_LIMIT');
        const text = pending.slice(0, newline); pending = pending.slice(newline + 1);
        need(text.length > 0, 'DATASET_EMPTY_ROW');
        need(++count <= this.manifest.dataset.rows, 'DATASET_ROW_COUNT_CHANGED');
        yield this._row(text);
      }
      need(pending.length <= maxRowCharacters, 'DATASET_ROW_LIMIT');
    }
    pending += decoder.decode();
    if (pending) { count++; yield this._row(pending); }
    need(count === this.manifest.dataset.rows, 'DATASET_ROW_COUNT_CHANGED');
  }
  /** Returns only after the entire output has passed its saved size/hash check. */
  async readRows({limit = 8388608, maxRows = 100000, signal} = {}) {
    need(Number.isSafeInteger(maxRows) && maxRows >= 0 && this.manifest.dataset.rows <= maxRows,
      'DATASET_ROW_LIMIT_EXCEEDED_USE_ROWS');
    const bytes = await this.file('dataset.jsonl').bytes({limit, signal});
    const text = new TextDecoder('utf-8', {fatal:true}).decode(bytes);
    const lines = text.length ? text.replace(/\n$/, '').split('\n') : [];
    need(lines.length === this.manifest.dataset.rows, 'DATASET_ROW_COUNT_CHANGED');
    return lines.map(line => this._row(line));
  }
}

// MIT. Explicit original reserved-attempt successors, with separate source predicates.
import {readdir,rename} from 'node:fs/promises';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';
import {randomUUID} from 'node:crypto';
import {privateDirectory,readBytes,readJson,writeJson,jsonBytes,parseJson,digest,
  exists,intent,need,object,now,syncDirectory,absolute,BuyerError} from './store.mjs';
import {inspectNodeLostOutput} from './lost-output.mjs';
import {readAuthorizationExpiryEvidence} from './expiry-evidence.mjs';
import {readUndispatchedAuthorizationEvidence} from './authorization-dispatch.mjs';
import {readContinuationOperation,continuationRequestIdentity,withContinuationLock,
  readUnpaidContinuationEdge} from './unpaid-continuation.mjs';

const OP_SCHEMA='stellar-forge.node-buyer.v1';
const copy=value=>parseJson(jsonBytes(value));
const canonical=value=>JSON.stringify(value,(_key,item)=>object(item)
  ?Object.fromEntries(Object.keys(item).sort().map(key=>[key,item[key]])):item);
const same=(left,right)=>canonical(left)===canonical(right);
const sha=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
function checkSignal(signal){
  need(signal===undefined||signal instanceof AbortSignal,'INVALID_ABORT_SIGNAL');
  need(!signal?.aborted,'OPERATION_ABORTED_BEFORE_START');
}
const runtimeImport=(operation,name)=>import(pathToFileURL(join(operation.buyer.runtime.directory,name)).href);

function reservedFamily(mode){
  const isExpired=mode==='expired';
  const SCHEMA='stellar-forge.node-'+mode+'-continuation.v1';
  const CHOICE=mode+'-continuation.json',READY=mode+'-continuation-ready.json';
  const markerKey=mode+'Continuation',evidenceKey=isExpired?'expiry':'authorization';
  const inputsKey=isExpired?'expiryInputs':'authorizationInputs';
  const descriptorFile=mode+'-reservation-source.json';
  const code=suffix=>mode.toUpperCase()+'_CONTINUATION_'+suffix;
  const readEvidence=(operation,inputs,signal)=>isExpired?
    readAuthorizationExpiryEvidence({...inputs,signal}):
    readUndispatchedAuthorizationEvidence(operation,{...inputs,signal});
async function immutable(path,value){
  try{await writeJson(path,value,{exclusive:true});}
  catch(error){if(error.code!=='EEXIST')throw error;}
  const raw=await readBytes(path),saved=parseJson(raw);
  need(same(saved,value),code('SOURCE_CONFLICT'));
  return{raw,value:saved,sha256:digest(raw)};
}
async function selected(operation){
  const path=join(operation.directory,CHOICE);
  if(!await exists(path))return null;
  const raw=await readBytes(path),value=parseJson(raw);
  need(value.schema===SCHEMA&&value.parentIntentId===operation.intentId&&
    intent(value.intentId)!==operation.intentId&&object(value.source)&&
    value.source.intentId===operation.intentId&&sha(value.source.expectedRequestSha256)&&
    sha(value[evidenceKey]?.sha256)&&object(value[inputsKey])&&object(value.reservation)&&
    typeof value.reason==='string'&&value.reason.length>0,
    code('CHOICE_INVALID'));
  return{raw,value,sha256:digest(raw)};
}
const marker=choice=>({parentIntentId:choice.value.parentIntentId,choiceSha256:choice.sha256});

async function originalFiles(operation,source){
  const bound=await readContinuationOperation(operation);
  need(bound.operationSha256===source.sourceHashes.operation&&
    bound.configSha256===source.configSha256&&bound.bodySha256===source.bodySha256&&
    bound.ticketSha256===source.ticketSha256&&
    (bound.meta.nativeWorkspace??null)===source.nativeWorkspace&&
    continuationRequestIdentity(bound.config)===source.requestIdentity,
    code('PARENT_CHANGED'));
  const known={attempt:join(operation.directory,'attempt.json'),
    stdout:join(operation.directory,'stdout.json'),stderr:join(operation.directory,'stderr.log'),
    result:join(operation.directory,'result.json'),response:join(operation.directory,'response.bin'),
    evidence:join(bound.config.evidenceDir,digest(operation.intentId)+'.json'),
    workspaceConfig:join(source.workspace,'operator.json'),workspaceManifest:join(source.workspace,'workspace.json')};
  for(const [key,path]of Object.entries(known)){
    const expected=source.sourceHashes[key];
    if(expected===undefined)continue;
    if(expected===null){need(!await exists(path),code('PARENT_OUTPUT_CHANGED'));continue;}
    need(sha(expected),code('SOURCE_INVALID'));
    const limit=key==='stdout'||key==='stderr'?33_554_432:key==='result'?16_777_216:4_000_000;
    need(digest(await readBytes(path,limit))===expected,code('PARENT_OUTPUT_CHANGED'));
  }
  return bound;
}
async function recheckEvidence(operation,choice){
  const evidence=await readEvidence(operation,choice.value[inputsKey]);
  need(evidence.sha256===choice.value[evidenceKey].sha256&&same(evidence,choice.value[evidenceKey]),
    code(isExpired?'EXPIRY_SOURCE_CHANGED':'AUTHORIZATION_SOURCE_CHANGED'));
  return evidence;
}
async function childBinding(parent,choice,child,{ready=true}={}){
  const bound=await originalFiles(parent,choice.value.source);
  await recheckEvidence(parent,choice);
  const next=await readContinuationOperation(child);
  need(child.intentId===choice.value.intentId&&same(next.meta[markerKey],marker(choice))&&
    ['unpaidContinuation','expiredContinuation','undispatchedContinuation'].every(key=>key===markerKey||next.meta[key]===undefined)&&
    next.bodySha256===bound.bodySha256&&next.ticketSha256===bound.ticketSha256&&
    (next.meta.nativeWorkspace??null)===(bound.meta.nativeWorkspace??null)&&
    continuationRequestIdentity(next.config)===choice.value.source.requestIdentity&&
    (bound.meta.nativeWorkspace===undefined||next.config.evidenceDir===bound.config.evidenceDir),
    code('CHILD_CHANGED'));
  const hashes={operationSha256:next.operationSha256,configSha256:next.configSha256,
    bodySha256:next.bodySha256,ticketSha256:next.ticketSha256};
  if(ready){
    need(await exists(join(parent.directory,READY)),code('PREPARATION_INCOMPLETE'));
    const completed=await readJson(join(parent.directory,READY));
    need(completed.schema===SCHEMA&&completed.parentIntentId===parent.intentId&&
      completed.intentId===child.intentId&&completed.choiceSha256===choice.sha256&&
      same(completed.child,hashes),code('PREPARATION_INCOMPLETE'));
  }
  return{bound,next,hashes};
}
async function edge(operation,meta){
  need(object(meta[markerKey]),code('LINEAGE_INVALID'));
  const parent=operation.buyer.operation(intent(meta[markerKey].parentIntentId));
  const choice=await selected(parent);
  need(choice&&choice.sha256===meta[markerKey].choiceSha256&&
    choice.value.intentId===operation.intentId,code('CHOICE_CHANGED'));
  const {bound}=await childBinding(parent,choice,operation);
  return{operation:parent,meta:bound.meta};
}

async function auditedReservation(operation,snapshot,approvedRequest,{signal,environment,node}){
  const descriptor={schema:'stellar-forge.sf88.node-reservation-source.v1',sourceKind:'node-operation',
    stateDirectory:snapshot.stateDirectory,operationDirectory:snapshot.operationDirectory,
    runtimeDirectory:snapshot.runtimeDirectory,workspace:snapshot.workspace,intentId:snapshot.intentId,
    attemptId:snapshot.attemptId,configSha256:snapshot.configSha256,requestSha256:snapshot.expectedRequestSha256,
    sourceHashes:snapshot.sourceHashes,evidenceState:snapshot.evidenceState,localOutcome:snapshot.localOutcome,
    transportCheckpointSha256:snapshot.transportCheckpointSha256,approvedRequest};
  const source=await immutable(join(operation.directory,descriptorFile),descriptor);
  const [{openWorkspace},{runOriginalFinalityWorker}]=await Promise.all([
    runtimeImport(operation,'workspace.mjs'),runtimeImport(operation,'finalization.mjs')]);
  const active=await openWorkspace(['--dir',snapshot.workspace],{accounting:true,environment});
  const owner=active.config.operator;
  need(active.config.trustedPayer===snapshot.expected.payer,code('PAYER_CHANGED'));
  const result=await runOriginalFinalityWorker(owner.python,[
    '--node-reservation-source',join(operation.directory,descriptorFile),
    '--ledger',owner.ledger,'--policy',owner.policy,'--payer',snapshot.expected.payer,
    '--node',node,'--reports',operation.directory,'--expected-request-sha',snapshot.expectedRequestSha256,
    '--verify-only'],active.operatorEnvironment,signal,undefined,environment);
  need(result?.outcome==='RESERVATION_VERIFIED',
    typeof result?.reason==='string'&&/^[A-Z][A-Z0-9_]{1,119}$/.test(result.reason)?
      result.reason:code('ORIGINAL_RESERVATION_AUDIT_FAILED'));
  const row=result.reservation,binding=result.binding;
  need(binding?.intentId===operation.intentId&&
    binding.requestSha256===snapshot.expectedRequestSha256&&binding.attemptId===snapshot.attemptId&&
    binding.configSha256===snapshot.configSha256&&same(binding.sourceHashes,snapshot.sourceHashes)&&
    row?.request_id===operation.intentId&&row.request_digest===snapshot.expectedRequestSha256&&
    row.state==='reserved'&&row.actual==='0'&&row.receipt_ref===''&&row.proof_sha256===''&&
    row.amount===approvedRequest.max_amount&&row.actor===approvedRequest.actor&&
    row.service===approvedRequest.service&&row.network===approvedRequest.network&&row.asset===approvedRequest.asset,
    code('ORIGINAL_RESERVED_ROW_REQUIRED'));
  return{...row,sourceSha256:source.sha256,recordAuthority:result.recordAuthority};
}

async function prepare(operation,options={}){
  const {intentId,expectedRequestSha256,expectedAttemptId,expectedConfigSha256,reason,
    workspace,approvedRequest:inputRequest,approvedRequestFile,expiryEvidence,
    signal,node=process.execPath,environment=process.env,...extra}=options;
  need(Object.keys(extra).length===0,code('FIELDS_INVALID'));
  intent(intentId);
  need(intentId!==operation.intentId&&sha(expectedRequestSha256)&&sha(expectedAttemptId),
    code('SELECTION_REQUIRED'));
  need(typeof reason==='string'&&reason===reason.trim()&&reason.length>0&&reason.length<=1000&&
    !/[\x00-\x1f\x7f]/.test(reason),code('REMEDIATION_REQUIRED'));
  need(isExpired?object(expiryEvidence)&&Object.keys(expiryEvidence).every(key=>
    ['boundFile','observationFile','expectedFeeAccount','providerSourceFile','sdkSourceIndexFile'].includes(key)):
    expiryEvidence===undefined,code('EVIDENCE_INPUT_REQUIRED'));
  need((inputRequest!==undefined)!==(approvedRequestFile!==undefined),
    code('ONE_APPROVED_REQUEST_REQUIRED'));
  const approvedRequest=inputRequest===undefined?null:copy(inputRequest);
  const inputs=isExpired?copy(expiryEvidence):{},workerEnvironment={...environment};
  for(const key of ['boundFile','observationFile','providerSourceFile','sdkSourceIndexFile'])
    if(inputs[key]!==undefined)inputs[key]=absolute(inputs[key]);
