const SCHEMA = 'stellar-forge.sf88.authorization-expiry-evidence.v1';
const TESTNET = 'Test SDF Network ; September 2015';
const HASH = /^[a-f0-9]{64}$/;
const ACCOUNT = /^G[A-Z2-7]{55}$/;
const TOTAL_LIMIT = 32 * 1024 * 1024;
