    files[0].name === document.filename, 'UNSTRUCTURED_ORIGINAL_DOCUMENT_CHANGED');
  return { parameters, parametersSha256: digest(canonicalBytes(parameters)),
    document: { ...document, ...encoded(bytes) } };
}

