  try { saved = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(raw)); }
  catch { throw new InputError('DISCOVERY_JSON_INVALID'); }
  need(object(saved), 'INVALID_SAVED_DISCOVERY');
