  need(Number.isInteger(accepted.maxTimeoutSeconds) && accepted.maxTimeoutSeconds >= 1 &&
    accepted.maxTimeoutSeconds <= 86400 &&
    (accepted.extra === undefined || object(accepted.extra)), 'INVALID_DISCOVERED_REQUIREMENT');
